const item = $input.first();
const form = item.json || {};
const binary = item.binary || {};

const getField = (name, fallback = '') => {
  const value = form[name];
  if (value === undefined || value === null || value === '') return fallback;

  // n8n dropdown multiselect / checkbox fields may return arrays.
  // Normalize them to a clean comma-separated string for the AI prompt and HTML report.
  if (Array.isArray(value)) {
    const cleaned = value
      .map(v => String(v).trim())
      .filter(Boolean);
    return cleaned.length ? cleaned.join(', ') : fallback;
  }

  if (typeof value === 'string') return value.trim();
  return value;
};

const category = getField('Product Category', 'Area Rugs');
const focus = getField('Focus Area', '');
const targetAudience = getField('Target Audience', 'General home shoppers');
const campaignGoal = getField('Campaign Goal', 'Content engagement');
const season = getField('Season / Occasion', 'Evergreen');
const primaryChannel = getField('Primary Channel', 'Multi-channel');
const competitorFocus = getField('Competitor Focus', '');
const productFocus = getField('Product Focus', '');
const kpiFocus = getField('KPI Focus', 'Engagement and conversion');

const normalizeKey = (s = '') =>
  String(s).toLowerCase().replace(/[^a-z0-9]/g, '');

async function readBinaryProperty(propName) {
  try {
    const buf = await this.helpers.getBinaryDataBuffer(0, propName);
    return buf.toString('utf8');
  } catch (e) {
    return '';
  }
}

async function extractFile(fieldName, ordinal = 0) {
  const jsonValue = form[fieldName];

  // 1) Direct string content
  if (typeof jsonValue === 'string' && /<[^>]+>/.test(jsonValue)) {
    return jsonValue;
  }

  // 2) JSON object containing base64 data
  if (jsonValue && typeof jsonValue === 'object' && jsonValue.data) {
    try {
      return Buffer.from(jsonValue.data, 'base64').toString('utf8');
    } catch (e) {}
  }

  // 3) Exact binary property match
  if (binary[fieldName]) {
    const txt = await readBinaryProperty.call(this, fieldName);
    if (txt) return txt;
  }

  // 4) Normalized binary key match
  const target = normalizeKey(fieldName);
  for (const key of Object.keys(binary)) {
    if (normalizeKey(key) === target) {
      const txt = await readBinaryProperty.call(this, key);
      if (txt) return txt;
    }
  }

  // 5) Match by uploaded filename / field-like metadata
  const entries = Object.entries(binary);
  for (const [key, meta] of entries) {
    const haystack = normalizeKey(
      `${key} ${meta?.fileName || ''} ${meta?.fileExtension || ''}`
    );
    const tokens = fieldName
      .toLowerCase()
      .split(/\s+/)
      .filter(t => t.length >= 2)
      .map(normalizeKey);

    const score = tokens.filter(t => haystack.includes(t)).length;
    if (score >= 2) {
      const txt = await readBinaryProperty.call(this, key);
      if (txt) return txt;
    }
  }

  // 6) Final fallback: use HTML files by order
  const htmlCandidates = entries.filter(([_, meta]) => {
    const mime = String(meta?.mimeType || '').toLowerCase();
    const name = String(meta?.fileName || '').toLowerCase();
    return mime.includes('html') || name.endsWith('.html');
  });

  if (htmlCandidates[ordinal]) {
    const txt = await readBinaryProperty.call(this, htmlCandidates[ordinal][0]);
    if (txt) return txt;
  }

  return '';
}

const stripHtml = (html = '') => {
  return String(html)
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<\/(p|div|section|article|li|h[1-6]|tr)>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n')
    .trim();
};

