const input = $input.first().json || {};
const rawOutput = input.output ?? input.text ?? '';
const source = $('Extract & Normalize Inputs').first().json;

let raw = String(rawOutput)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

const match = raw.match(/\{[\s\S]*\}/);
if (match) raw = match[0];

let content = null;
let parseError = '';

try {
  content = JSON.parse(raw);
} catch (e) {
  parseError = e.message;
  content = {
    key_metrics: [],
    data_foundation: { p2_insights: [], p3_insights: [] },
    executive_summary: '',
    executive_recommendation: {},
    brand_voice: {},
    why_this_feels_wayfair: '',
    audience_strategy: {},
    hero_recommendation: {},
    content_ideas: [],
    content_funnel: [],
    social_captions: {
      instagram: [],
      pinterest: [],
      facebook: [],
      tiktok: []
    },
    campaigns: [],
    competitive_angles: [],
    content_priorities: [],
    performance_plan: [],
    quick_wins: []
  };
}

// Fallback protection: if the model ever echoes n8n template placeholders,
// resolve the common campaign-context placeholders before the report is built.
const replacements = {
  '{{ $json.category }}': source.category || '',
  '{{ $json.focus }}': source.focus || '',
  '{{ $json.target_audience }}': source.target_audience || '',
  '{{ $json.campaign_goal }}': source.campaign_goal || '',
  '{{ $json.season }}': source.season || '',
  '{{ $json.primary_channel }}': source.primary_channel || '',
  '{{ $json.competitor_focus }}': source.competitor_focus || '',
  '{{ $json.product_focus }}': source.product_focus || '',
  '{{ $json.kpi_focus }}': source.kpi_focus || ''
};

const resolveString = (s) => {
  let out = String(s ?? '');
  for (const [needle, value] of Object.entries(replacements)) {
    out = out.split(needle).join(String(value ?? ''));
  }
  // Remove any still-unresolved simple $json placeholder rather than exposing it.
  out = out.replace(/\{\{\s*\$json\.[^}]+\}\}/g, '');
  return out;
};

const resolveDeep = (value) => {
  if (Array.isArray(value)) return value.map(resolveDeep);
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value).map(([k, v]) => [k, resolveDeep(v)])
    );
  }
  if (typeof value === 'string') return resolveString(value);
  return value;
};

content = resolveDeep(content);

return [{
  json: {
    content,
    category: source.category,
    focus: source.focus,
    target_audience: source.target_audience,
    campaign_goal: source.campaign_goal,
    season: source.season,
    primary_channel: source.primary_channel,
    competitor_focus: source.competitor_focus,
    product_focus: source.product_focus,
    kpi_focus: source.kpi_focus,
    input_metadata: source.metadata,
    parse_status: parseError ? 'error' : 'ok',
    parse_error: parseError,
    raw_output_preview: parseError ? raw.slice(0, 1500) : ''
  }
}];

const data = $input.first().json || {};
const c = data.content || {};

const arr = (v) => Array.isArray(v) ? v : [];
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const text = (v, fallback = '') =>
  (v === undefined || v === null) ? fallback : String(v).trim();

const normalizeMetrics = arr(c.key_metrics)
  .filter(x => x && (x.value || x.label))
  .map(x => ({
