  key_metrics: normalizeMetrics,
  data_foundation: {
    p2_insights: arr(obj(c.data_foundation).p2_insights).map(x => text(x)).filter(Boolean),
    p3_insights: arr(obj(c.data_foundation).p3_insights).map(x => text(x)).filter(Boolean)
  },
  executive_summary: text(c.executive_summary),
  executive_recommendation: {
    primary_opportunity: text(execRec.primary_opportunity),
    why_it_matters: text(execRec.why_it_matters),
    recommended_move: text(execRec.recommended_move)
  },
  brand_voice: {
    tone: text(brand.tone),
    commercial_human_balance: text(brand.commercial_human_balance),
    emotion_evoked: text(brand.emotion_evoked),
    cta_style: text(brand.cta_style),
    avoid: arr(brand.avoid).map(x => text(x)).filter(Boolean),
    ai_agent_emulation: text(brand.ai_agent_emulation)
  },
  why_this_feels_wayfair: text(c.why_this_feels_wayfair),
  audience_strategy: {
