    content: text(x?.content),
    message: text(x?.message),
    cta: text(x?.cta),
    kpi: text(x?.kpi)
  })),
  social_captions: {
    instagram: arr(social.instagram).map(x => ({
      caption: text(x?.caption),
      hashtags: arr(x?.hashtags).map(h => text(h)).filter(Boolean),
      visual_direction: text(x?.visual_direction),
      goal: text(x?.goal)
    })),
    pinterest: arr(social.pinterest).map(x => ({
      title: text(x?.title),
      description: text(x?.description),
      visual_direction: text(x?.visual_direction),
      goal: text(x?.goal)
    })),
    facebook: arr(social.facebook).map(x => ({
      post: text(x?.post),
      visual_direction: text(x?.visual_direction),
      goal: text(x?.goal)
    })),
    tiktok: arr(social.tiktok).map(x => ({
      hook: text(x?.hook),
      script: text(x?.script),
      cta: text(x?.cta),
      visual_direction: text(x?.visual_direction),
      goal: text(x?.goal)
    }))
  },
  campaigns: arr(c.campaigns).map(x => ({
    name: text(x?.name, 'Campaign'),
    tagline: text(x?.tagline),
    description: text(x?.description),
    details: obj(x?.details)
  })),
  competitive_angles: arr(c.competitive_angles).map(x => ({
    title: text(x?.title),
    competitor_gap: text(x?.competitor_gap),
    wayfair_opportunity: text(x?.wayfair_opportunity),
    source_basis: text(x?.source_basis)
  })),
  content_priorities: arr(c.content_priorities)
    .map((x, i) => ({
      priority: Number(x?.priority) || i + 1,
      title: text(x?.title, `Priority ${i + 1}`),
      rationale: text(x?.rationale),
      effort: text(x?.effort, 'Not specified'),
      impact: text(x?.impact, 'Not specified')
    }))
    .sort((a, b) => a.priority - b.priority),
  performance_plan: arr(c.performance_plan).map(x => ({
    content_or_campaign: text(x?.content_or_campaign),
    primary_kpi: text(x?.primary_kpi, data.kpi_focus),
    secondary_kpi: text(x?.secondary_kpi),
    success_target: text(x?.success_target, 'Beat current baseline'),
    test_hypothesis: text(x?.test_hypothesis),
    variant_a: text(x?.variant_a),
    variant_b: text(x?.variant_b),
    optimization_action: text(x?.optimization_action)
  })),
  quick_wins: arr(c.quick_wins).map(x => ({
    action: text(x?.action),
    why_now: text(x?.why_now),
    owner: text(x?.owner)
  }))
};

const warnings = [
  ...arr(data.input_metadata?.warnings),
  ...(data.parse_status === 'error'
    ? [`AI JSON parsing failed: ${data.parse_error}`]
    : []),
  ...(normalized.key_metrics.length === 0
    ? ['No source-supported key metrics were returned.']
    : []),
  ...(normalized.data_foundation.p2_insights.length === 0
    ? ['No Project 2 insights were returned.']
    : []),
  ...(normalized.data_foundation.p3_insights.length === 0
    ? ['No Project 3 insights were returned.']
    : [])
];

return [{
  json: {
    ...data,
    content: normalized,
    quality: {
      warning_count: warnings.length,
      warnings,
      counts: {
        key_metrics: normalized.key_metrics.length,
        p2_insights: normalized.data_foundation.p2_insights.length,
        p3_insights: normalized.data_foundation.p3_insights.length,
        content_ideas: normalized.content_ideas.length,
        funnel_rows: normalized.content_funnel.length,
        campaigns: normalized.campaigns.length,
        performance_tests: normalized.performance_plan.length,
        quick_wins: normalized.quick_wins.length
      }
    }
  }
}];

const data = $input.first().json || {};
